const x = $json.body ?? $json;
// This webhook requires Header Auth. Only the trusted staff-approval backend should hold that credential.
if (x.approved !== true) return [{json:{send:false,status:'pending_review',message:'Email not sent: approval required.'}}];
const type = String(x.type || 'notice');
if (!['notice','deadline','event','resource'].includes(type)) throw new Error('Unsupported email type');
const title = String(x.title || '').trim();
const details = String(x.details || '').trim();
if (title.length < 3 || title.length > 160 || details.length < 3 || details.length > 5000) throw new Error('Invalid title/details');
return [{json:{send:true,type,title,details,audience:String(x.audience || 'AI & DS students').slice(0,100),date:String(x.date || '').slice(0,40),receivedAt:new Date().toISOString()}}];
